(function(){
  const TWO_PI = 2 * Math.PI;
  const count = 6;
  const center = [10.55, 4.1];
  const radius = 0.75;
  const placements = [];
  const step = TWO_PI / count;
  for (let i = 0; i < count; i++) {
    const angle = i * step;
    const x = center[0] + radius * Math.cos(angle);
    const z = center[1] + radius * Math.sin(angle);
    const rotation = Math.atan2(-Math.cos(angle), -Math.sin(angle));
    placements.push({ position: [x, z], rotation });
  }
  const st = window.__store.getState();
  const seedItem = st.items.find(it => it.id === 'chair-seed');
  if (!seedItem) throw new Error('seed chair not found');
  const gid = 'radial-grp-test';
  const newItems = placements.map((p, i) => ({
    ...seedItem,
    id: 'radial-chair-' + i,
    position: p.position,
    rotation: p.rotation,
    props: { ...seedItem.props },
    groupId: gid
  }));
  const updatedSeed = { ...seedItem, groupId: gid };
  st.setItems(st.items.filter(it => it.id !== 'chair-seed').concat([updatedSeed]).concat(newItems));
  st.selectItem(null);
})()

